"""
The `metadata/_platform` snapshots: generated by the registry, read-only in squad repos.

Each snapshot starts with a header line carrying the sha256 of everything after it, so a hand edit is
detected offline (`make validate-metadata`, CI). The same header works in YAML and Turtle, both of
which treat `#` as a comment.
"""

from __future__ import annotations

import hashlib
from pathlib import Path
from typing import Any

import yaml
from rdflib import Graph

HEADER = (
    "# machine-owned: generated by dbx-platform-registry; do not edit; change it through the registry. content-sha256="
)
SNAPSHOT_FILES = ("repo.yaml", "teams.yaml", "domains.yaml", "glossary.ttl")


def _digest(body: str) -> str:
    return hashlib.sha256(body.encode("utf-8")).hexdigest()


def with_header(body: str) -> str:
    """Return `body` (normalised to end with exactly one newline) preceded by its hash header."""
    body = body.rstrip("\n") + "\n"
    return f"{HEADER}{_digest(body)}\n{body}"


def strip_header(text: str) -> str:
    """Return the body of a snapshot, without its header line (the text itself if it has none)."""
    first, _, rest = text.partition("\n")
    return rest if first.startswith(HEADER) else text


def check_text(text: str) -> str | None:
    """Return a description of what is wrong with a snapshot's header, or None if it is intact."""
    first, _, body = text.partition("\n")
    if not first.startswith(HEADER):
        return "missing the machine-owned hash header"
    recorded = first.removeprefix(HEADER)
    if recorded != _digest(body):
        return "content does not match its hash header (edited by hand?); change it through the registry"
    return None


def verify_directory(directory: Path) -> list[tuple[str, str]]:
    """Return `(file name, problem)` for every snapshot that is missing or edited."""
    problems = []
    for name in SNAPSHOT_FILES:
        path = directory / name
        if not path.is_file():
            problems.append((name, "missing"))
            continue
        problem = check_text(path.read_text(encoding="utf-8"))
        if problem:
            problems.append((name, problem))
    return problems


def _dump(document: dict[str, Any]) -> str:
    return yaml.safe_dump(document, sort_keys=False, allow_unicode=True, width=119)


def repo_document(registration: dict[str, Any], settings: dict[str, Any]) -> dict[str, Any]:
    """Return the `repo.yaml` content for a registration."""
    return {
        "project_id": registration["project_id"],
        "kind": registration["kind"],
        "domain": registration["domain"],
        "project": {
            "title": registration["squad"]["title"],
            "project_type": "TEAM",
            "owner_team": registration["squad"]["name"],
        },
        "service_principal": registration["service_principal"],
        "tags": registration["tags"],
        "iri_base": settings["iri_base"],
        "standards": settings["standards"],
    }


def teams_document(registration: dict[str, Any]) -> dict[str, Any]:
    """Return the `teams.yaml` content for a registration: the squad, its contacts and its AD groups."""
    squad = registration["squad"]
    return {
        "teams": [
            {
                "name": squad["name"],
                "title": squad["title"],
                "domain": registration["domain"],
                "github_team": squad["github_team"],
                "contacts": registration["contacts"],
                "groups": registration["groups"],
            }
        ]
    }


def merge_glossary(directory: Path) -> str:
    """Return every `*.ttl` under `directory` merged into one Turtle document (deterministic order)."""
    graph = Graph()
    for path in sorted(directory.glob("*.ttl")):
        graph.parse(path, format="turtle")
    return graph.serialize(format="turtle")


def render_registry_project(root: Path, project_id: str) -> dict[str, str]:
    """Render the four snapshot files for `project_id` from a registry checkout at `root`."""
    registration = yaml.safe_load((root / "projects" / f"{project_id}.yaml").read_text(encoding="utf-8"))
    settings = yaml.safe_load((root / "settings.yaml").read_text(encoding="utf-8"))
    domains = (root / "domains.yaml").read_text(encoding="utf-8")
    return render_snapshots(registration, settings, domains, merge_glossary(root / "glossary"))


def render_snapshots(
    registration: dict[str, Any], settings: dict[str, Any], domains_text: str, glossary_text: str
) -> dict[str, str]:
    """Return the four snapshot files (name -> text with hash header) for one registration."""
    return {
        "repo.yaml": with_header(_dump(repo_document(registration, settings))),
        "teams.yaml": with_header(_dump(teams_document(registration))),
        "domains.yaml": with_header(strip_header(domains_text)),
        "glossary.ttl": with_header(strip_header(glossary_text)),
    }
